/**
 * Made-to-order shower configurations, not stocked SKUs or engineering approval.
 * Geometry, moving leaves and hinge support define a model. Handing, dimensions,
 * hardware finish and installation base stay project parameters, not extra pages.
 * Research: docs/showers-research-{a,b,c}.md. Copy is original, not supplier copy.
 */
const GLASS = 'Прозрачное осветлённое стекло CrystalVision без зелёного оттенка';
const B = (id, title, intro, children, selectionHint = 'Выберите состав и расположение входа.') => ({
  id, title, intro, status: 'structure', selectionHint, children,
});
const L = (id, title, intro, solutionId, preset) => ({
  id, title, intro, kind: 'solution', solutionId, status: 'structure',
  preset: { mode: 'installation', glass: GLASS, ...preset, title,
    note: preset.note || 'Размеры, свободный проход и подходящую систему фурнитуры согласуем по плану помещения.' },
});
const V = (id, title, intro, solutionId, common, choices, selectionHint) => B(
  id, title, intro,
  choices.map(({ id: suffix, title: name, intro: text, solutionId: modelSolutionId, ...preset }) =>
    L(`${id}-${suffix}`, name, text, modelSolutionId || solutionId, { ...common, ...preset })),
  selectionHint,
);

