function refineShowerDetails(node) {
  if (node.children) return { ...node, children: node.children.map(refineShowerDetails) };
  let choices;
  if (node.id === 'showers-niche-folding-with-fixed') {
    choices = [
      { id: 'wall-hinged', title: 'Книжка на стене с неподвижным добором',
        intro: 'Две складные секции опираются на стену; противоположную часть проёма занимает неподвижный добор.',
        mounting: 'Опорные петли стена—стекло и межстворчатые складные петли', hingeSupport: 'Стена—стекло',
        configuration: '2 складные секции на стене + 1 неподвижный добор',
        note: 'Проверим парковку книжки у стены и примыкание её свободного края к неподвижному добору.' },
      { id: 'glass-hinged', title: 'Книжка на неподвижном доборе',
        intro: 'Складная дверь опирается на закреплённый добор; секции складываются у стеклянной опоры.',
        mounting: 'Опорные петли стекло—стекло и межстворчатые складные петли', hingeSupport: 'Стекло—стекло',
        configuration: '1 неподвижный опорный добор + 2 навешенные складные секции',
        note: 'Опора на добор и его стабилизация проверяются вместе с документацией конкретной складной системы.' },
    ];
  } else if (node.id === 'showers-custom-cutout') {
    choices = [
      { id: 'wall-projection', title: 'Душевой экран с обходом выступа стены',
        intro: 'Индивидуальный вырез повторяет выступ стены или инсталляционный короб рядом с душевой зоной.',
        geometry: 'Плоское стекло с вырезом по выступу стены', configuration: 'Неподвижный экран с обходом стенового выступа',
        mounting: 'К несущим участкам стены и основанию; узлы по месту',
        note: 'Нужны контур, глубина и высоты выступа; размеры выреза согласуются до изготовления.' },
      { id: 'bench', title: 'Душевой экран с обходом скамьи',
        intro: 'Нижний контур панели учитывает встроенную скамью или подиум внутри душевой.',
        geometry: 'Плоское стекло с вырезом в нижней части', configuration: 'Неподвижный экран с обходом скамьи или подиума',
        mounting: 'К стене и согласованным опорным участкам основания',
        note: 'Проверим высоту и глубину скамьи, примыкания и возможность выполнения выреза в выбранном стекле.' },
    ];
  }
  if (!choices) return node;
  const { title, note, ...inherited } = node.preset;
  return B(node.id, node.title, node.intro,
    choices.map(({ id, title: name, intro, ...preset }) =>
      L(`${node.id}-${id}`, name, intro, node.solutionId, { ...inherited, ...preset })),
    node.id === 'showers-custom-cutout' ? 'Выберите, какой элемент требуется обойти.' : 'Выберите опору складной двери.');
}

